class PhoneNumber:
    def __init__(self, number):
        # Remove known punctuation / formatting characters.
        for char in (" ", "-", ".", "(", ")", "+"):
            number = number.replace(char, "")

        # Validate the remaining characters.
        if any(c.isalpha() for c in number):
            raise ValueError("letters not permitted")
        if any(not c.isdigit() for c in number):
            raise ValueError("punctuations not permitted")

        # Validate the length.
        if len(number) < 10:
            raise ValueError("must not be fewer than 10 digits")
        if len(number) > 11:
            raise ValueError("must not be greater than 11 digits")

        # Strip the country code if present.
        if len(number) == 11:
            if number[0] != "1":
                raise ValueError("11 digits must start with 1")
            number = number[1:]

        self.number = number

        # Validate the area code.
        if number[0] == "0":
            raise ValueError("area code cannot start with zero")
        if number[0] == "1":
            raise ValueError("area code cannot start with one")

        # Validate the exchange code.
        if number[3] == "0":
            raise ValueError("exchange code cannot start with zero")
        if number[3] == "1":
            raise ValueError("exchange code cannot start with one")

    @property
    def area_code(self):
        return self.number[0:3]

    def pretty(self):
        return "({})-{}-{}".format(
            self.number[0:3], self.number[3:6], self.number[6:10]
        )

